hooks.command:
python3 -I -S -c 'exec("import hashlib,io,json,runpy,sys
from pathlib import Path
failure='"'"'Trusted local review artifacts failed integrity checks. Inspect .codex/hooks/stop_review.py and .opencodereview/, then re-trust the exact hook with /hooks.'"'"'
expected={'"'"'.codex/hooks/stop_review.py'"'"': '"'"'029b0d741f8c691395f07fb1724837a3c6873298a81e49325725f56accf3b47e'"'"', '"'"'.opencodereview/review-rules.md'"'"': '"'"'9ebce131b41d6307810bdd3a4678ef23cc241067e1295fdc0c8b0965b0fe3456'"'"', '"'"'.opencodereview/rule.json'"'"': '"'"'47d79f4f98173f96d7679c0f475a7aba3c524b1a82bef30e6f7ccaeb58ba0bad'"'"'}
raw=sys.stdin.read()
try:
 data=json.loads(raw)
 cwd=Path(data.get('"'"'cwd'"'"') or Path.cwd()).resolve(strict=True)
 root=next((p for p in (cwd,*cwd.parents) if (p/'"'"'.git'"'"').exists()),None)
 if root is None: raise RuntimeError('"'"'root'"'"')
 actual={name:hashlib.sha256((root/name).read_bytes()).hexdigest() for name in expected}
 if actual!=expected: raise RuntimeError('"'"'digest'"'"')
 sys.stdin=io.StringIO(raw)
 runpy.run_path(str(root/'"'"'.codex/hooks/stop_review.py'"'"'),run_name='"'"'__main__'"'"')
except Exception:
 print(json.dumps({'"'"'continue'"'"':False,'"'"'stopReason'"'"':failure},separators=('"'"','"'"','"'"':'"'"')))")'

